#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <vector>
#include "/root/ecc2k130/include/walk.h"
#define CHECK(call) do {cudaError_t e=(call);if(e!=cudaSuccess){std::fprintf(stderr,"%s: %s\n",#call,cudaGetErrorString(e));return 1;}} while(0)
int main(int argc,char **argv) {
    int devices=0; CHECK(cudaGetDeviceCount(&devices));
    if(devices!=1){std::fprintf(stderr,"expected one visible GPU, got %d\n",devices);return 1;}
    CHECK(cudaSetDevice(0));
    cudaDeviceProp prop{}; CHECK(cudaGetDeviceProperties(&prop,0));
    size_t before=0,total=0,after=0,afterTotal=0;
    CHECK(cudaMemGetInfo(&before,&total));
    const uint64_t slots=argc>1?std::strtoull(argv[1],nullptr,10):0;
    const uint64_t dpCap=argc>2?std::strtoull(argv[2],nullptr,10):65536;
    std::vector<void*> pointers;
    uint64_t requested=0;
    if(slots) {
        // Match PackedCudaEngine's polynomial-state allocation sizes. No
        // kernels run and no memory contents are initialized by this probe.
        const uint64_t bytes[]={slots*20,slots*20,slots*20,slots*20,
                                slots*4,slots*8,slots*8,dpCap*sizeof(DpRecord),8};
        for(uint64_t bytesForBuffer:bytes) {
            void *p=nullptr; CHECK(cudaMalloc(&p,size_t(bytesForBuffer)));
            pointers.push_back(p); requested+=bytesForBuffer;
        }
    }
    CHECK(cudaMemGetInfo(&after,&afterTotal));
    std::printf("{\"name\":\"%s\",\"visibleDevices\":%d,\"computeMajor\":%d,\"computeMinor\":%d,"
                "\"multiprocessors\":%d,\"l2CacheBytes\":%d,\"sharedBytesPerSM\":%llu,"
                "\"registersPerSM\":%d,\"maxThreadsPerSM\":%d,\"totalGlobalBytes\":%llu,"
                "\"runtimeTotalBytes\":%llu,\"freeBytesBefore\":%llu,\"freeBytesAfter\":%llu,"
                "\"slots\":%llu,\"dpRecordBytes\":%llu,\"requestedBufferBytes\":%llu,"
                "\"observedFreeMemoryDeltaBytes\":%lld}\n",
                prop.name,devices,prop.major,prop.minor,prop.multiProcessorCount,prop.l2CacheSize,
                (unsigned long long)prop.sharedMemPerMultiprocessor,prop.regsPerMultiprocessor,
                prop.maxThreadsPerMultiProcessor,(unsigned long long)prop.totalGlobalMem,
                (unsigned long long)total,(unsigned long long)before,(unsigned long long)after,
                (unsigned long long)slots,(unsigned long long)sizeof(DpRecord),
                (unsigned long long)requested,(long long)before-(long long)after);
    for(void *p:pointers) CHECK(cudaFree(p));
}
